// th14_s6_mb2 - TH14 v1.00b Stage 6 midboss non-spell 2.
// Source: st06mbs.ecl.txt MBoss2:141-193 (entry) + MBoss2_at:195-250 (dependency).
// Entry state: HP 13000, at (0,128), timer reset at MBoss2:147; native slot-0
// timeout 2100 frames (setInterrupt(0,0,2100,"MBossDead"), MBoss2:167).
// Card frame 0 = control spawn; source t0 starts after OPENING_BUFFER.

const TIME_LIMIT: int = 2524;   // 120 buffer + 2400 window (2100 native + 300 tail) + 4 startup
const OPENING_BUFFER: int = 120;

const BULLET_COLOR: int = 13;         // etSprite(0,15,13); SETSPRITE a=8 b=13
const BASE_SPEED: fx = 2fx;           // etSpeed(0,2.0,1.0) with 1 layer
const ANIM_BACKOFF: fx = 8fx;         // ANIM a=1 retreat: 4 * initial speed 2.0
const RING_STEP: angle = 7deg;        // 0.122173 rad per volley
const SECOND_OFFSET: angle = 6deg;    // pi/30 rad
const TURN_RATE: angle = 1deg;        // 0.017453 rad/frame, ANGLE_ACCEL s

// Per-bullet EX chain (MBoss2_at:213-218):
//   ANIM(a=1) -> VELTIME(30, target 1.0, keep angle) -> SETSPRITE(type 8, color 13)
//   -> PLAYSOUND(38) -> VELTIME(40, target 2.5) -> ANGLE_ACCEL(40, +-1deg/frame)
// Birth ANIM stage is omitted per policy; its 4*initial-speed retreat stays as a
// spawn-distance term in sh_dist. Both types share radius 2.4, so the sprite swap
// carries no radius difference. Sound/visual records omitted.
xformdef MB2_BULLET(turn: angle) {
    step_speed(1fx, 30 + 65536 * EASE_LINEAR);
    wait(30);
    set_sprite(TH14_RICE, BULLET_COLOR);
    step_speed(2.5fx, 40 + 65536 * EASE_LINEAR);
    wait(40);
    set_ang_vel(turn);
    wait(40);
    set_ang_vel(0deg);
}

async sub boss() {
    set_invuln(65535);
    // Frames from MBoss:21-22 (context): setHurtbox/setHitbox(48,48), 48 -> r24.
    set_hitbox(24fx);
    set_hurtbox(24fx);
    // MBoss2:160-166 clears the movement layers, then movePosTime(60,4,0,128).
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(140);   // MBoss2:171
    // MBoss2:172 moveLimit(0,128,280,96): no constant target write口, and the boss
    // emits without moving inside this window, so the clamp never binds.
    var n: int = 12;   // MBoss2:201-208 etCount stack: E12 / N30 / H36 / L48
    var rk: int = global(GVAR_RANK);
    if rk == 1 { n = 30; }
    if rk == 2 { n = 36; }
    if rk == 3 { n = 48; }
    wait(60);   // MBoss2:179 before @MBoss2_at()

    // MBoss2_at:198-219 emitter configuration (etSound omitted).
    sh_reset(0);
    sh_sprite(0, TH14_INVERT_RICE, BULLET_COLOR);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, n, 1);
    sh_speed(0, BASE_SPEED, 0fx);

    // MBoss2_at:220-224
    var a: angle = (rand(65536) - 32768) as angle;   // %RANDRAD, [-pi,pi)
    var b: fx = 96fx;                                // %B spawn distance
    var d: angle = a + SECOND_OFFSET;                // %D
    var c: angle = TURN_RATE;                        // %C, flips each volley

    // MBoss2_at:225-248: one volley every 9 frames until the 2100 native timeout.
    // 200 + 18*106 = 2108; last volley at t=2099 and the source interrupt lands at 2100.
    for pass in 0..106 {
        // etExSet(slot5, s=%C) / etAngle(%A) / etDist(%B) / etOn
        sh_xform(0, MB2_BULLET(c));
        sh_angle(0, a, 0deg);
        sh_dist(0, b - ANIM_BACKOFF);
        sh_fire(0);
        a = a + RING_STEP;
        if b > 0fx { b = b - 8fx; }
        c = 0deg - c;
        wait(9);
        // etExSet(slot5, s=-%C) / etAngle(%D) / etDist(%B) / etOn
        sh_xform(0, MB2_BULLET(c));
        sh_angle(0, d, 0deg);
        sh_dist(0, b - ANIM_BACKOFF);
        sh_fire(0);
        d = d - RING_STEP;
        if b > 0fx { b = b - 8fx; }
        c = 0deg - c;
        wait(9);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 13000, 0, 0, 0, boss);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

// TH14 synthetic type aliases; see transcribe/th14/bullet-types.md.
// Native 0..23 -> modern 0..23, 24..42 -> modern +1; value is the table row base.
const TH14_RICE: int = 480;          // native type 8
const TH14_INVERT_RICE: int = 592;   // native type 15
